class Solution { fun equationsPossible(equations:Array<String>):Boolean{val parent=IntArray(26){it};fun find(xInput:Int):Int{var x=xInput;while(parent[x]!=x){parent[x]=parent[parent[x]];x=parent[x]};return x};for(equation in equations)if(equation[1]=='=')parent[find(equation[0]-'a')]=find(equation[3]-'a');for(equation in equations)if(equation[1]=='!'&&find(equation[0]-'a')==find(equation[3]-'a'))return false;return true} }
